sys_script_include.script:
var detectmaliciousCode = Class.create();
detectmaliciousCode.prototype = {
    initialize: function() {},



    hasMaliciousCode: function(html) {
        if (!html)
            return false;

        html = String(html);

        //Disallowed / risky tags (open or close)
        var tagPatterns = [
            /<\/?\s*script\b/i,
            /<\/?\s*iframe\b/i,
            /<\/?\s*object\b/i,
            /<\/?\s*embed\b/i,
            /<\/?\s*svg\b/i,
            /<\/?\s*math\b/i,
            /<\/?\s*link\b[^>]*rel\s*=\s*["']?import["']?/i,
            /<meta\b[^>]*http-equiv\s*=\s*["']?refresh["']?[^>]*>/i
        ];

        //Dangerous attributes and URL schemes
        var attrPatterns = [
            /\son[a-z]+\s*=\s*["'][^"']*["']/i, // onload="...", onclick='...'
            /\son[a-z]+\s*=\s*[^>\s]+/i, // onload=doSomething()
            /(?:src|href)\s*=\s*["']\s*javascript\s*:/i,
            /(?:src|href)\s*=\s*["']\s*data\s*:[^"']*text\/html/i,
            /\ssrcdoc\s*=/i, // <iframe srcdoc=...>
            /\sstyle\s*=\s*["'][^"']*expression\s*\(/i, // CSS expression() – legacy but dangerous
            /\sstyle\s*=\s*["'][^"']*url\s*\(\s*["']?\s*javascript:/i
        ];

        //Suspicious JS keywords / functions
        var jsKeywordPatterns = [
            /document\.cookie/i,
            /document\.location/i,
            /window\.location/i,
            /localStorage/i,
            /sessionStorage/i,
            /XMLHttpRequest/i,
            /\bfetch\s*\(/i,
            /\beval\s*\(/i,
            /\bFunction\s*\(/i,
            /\bsetTimeout\s*\(/i,
            /\bsetInterval\s*\(/i
        ];

        //Basic obfuscation clues (very generic; may cause false positives)
        var obfuscationPatterns = [
            /\\x[0-9a-f]{2}/i, // \xNN
            /&#x[0-9a-f]+;/i, // hex HTML entities
            /&#\d+;/i, // decimal HTML entities
            /atob\s*\(/i, // atob( base64 )
            /unescape\s*\(/i
        ];

        var patterns = []
            .concat(tagPatterns)
            .concat(attrPatterns)
            .concat(jsKeywordPatterns)
            .concat(obfuscationPatterns);

        for (var i = 0; i < patterns.length; i++) {
            if (patterns[i].test(html)) {
                return true; // Something risky detected

				//add ITID alerts call here along with bubble ID or the taskize Case details
            }
        }

        return false; // No patterns matched
    },

    type: 'detectmaliciousCode'
};
